export type Role = "admin" | "member";

export interface User {
  username: string;
  password: string;
  role: Role;
}

export interface AuthOptions {
  users: User[];
  secret: string;
  now?: () => Date;
}

export function createAuthHandler(
  options: AuthOptions,
): (req: Request) => Promise<Response> {
  const { users, secret } = options;
  const now: () => Date = options.now ?? (() => new Date());

  const revokedTokens = new Set<string>();
  const userMap = new Map<string, User>();
  for (const u of users) userMap.set(u.username, u);

  const encoder = new TextEncoder();
  const decoder = new TextDecoder();

  function base64urlEncode(data: Uint8Array): string {
    let binary = "";
    for (let i = 0; i < data.length; i++) {
      binary += String.fromCharCode(data[i]);
    }
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function base64urlDecode(str: string): Uint8Array {
    let s = str.replace(/-/g, "+").replace(/_/g, "/");
    while (s.length % 4) s += "=";
    const binary = atob(s);
    const out = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
    return out;
  }

  async function computeHmac(message: string): Promise<Uint8Array> {
    const key = await crypto.subtle.importKey(
      "raw",
      encoder.encode(secret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"],
    );
    const sig = await crypto.subtle.sign("HMAC", key, encoder.encode(message));
    return new Uint8Array(sig);
  }

  function constantTimeEqual(a: string, b: string): boolean {
    if (a.length !== b.length) return false;
    let diff = 0;
    for (let i = 0; i < a.length; i++) {
      diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
    }
    return diff === 0;
  }

  async function generateToken(username: string, expiryMs: number): Promise<string> {
    const nonce = new Uint8Array(16);
    crypto.getRandomValues(nonce);
    const payload = JSON.stringify({ u: username, e: expiryMs, n: base64urlEncode(nonce) });
    const payloadB64 = base64urlEncode(encoder.encode(payload));
    const sig = await computeHmac(payloadB64);
    const sigB64 = base64urlEncode(sig);
    return `${payloadB64}.${sigB64}`;
  }

  async function verifyToken(token: string): Promise<User | null> {
    if (revokedTokens.has(token)) return null;

    const dotIdx = token.indexOf(".");
    if (dotIdx === -1 || dotIdx === token.length - 1) return null;
    // Actually, split by "." and check exactly 2 parts
    const parts = token.split(".");
    if (parts.length !== 2) return null;

    const [payloadB64, sigB64] = parts;
    if (!payloadB64 || !sigB64) return null;

    // Verify HMAC
    const expectedSig = await computeHmac(payloadB64);
    const expectedSigB64 = base64urlEncode(expectedSig);
    if (!constantTimeEqual(sigB64, expectedSigB64)) return null;

    // Decode payload
    let payload: string;
    try {
      payload = decoder.decode(base64urlDecode(payloadB64));
    } catch {
      return null;
    }

    let data: unknown;
    try {
      data = JSON.parse(payload);
    } catch {
      return null;
    }

    if (data === null || typeof data !== "object" || Array.isArray(data)) return null;
    const obj = data as Record<string, unknown>;
    const username = obj.u;
    const expiry = obj.e;
    if (typeof username !== "string" || typeof expiry !== "number") return null;

    // Check expiry
    if (now().getTime() >= expiry) return null;

    // Look up user
    const user = userMap.get(username);
    if (!user) return null;

    return user;
  }

  function jsonResponse(status: number, body: unknown): Response {
    return new Response(
      JSON.stringify(body),
      { status, headers: { "Content-Type": "application/json; charset=utf-8" } },
    );
  }

  function getTokenFromRequest(req: Request): string | null {
    const auth = req.headers.get("authorization");
    if (!auth) return null;
    const prefix = "Bearer ";
    if (!auth.startsWith(prefix)) return null;
    const token = auth.slice(prefix.length);
    if (!token) return null;
    return token;
  }

  return async (req: Request): Promise<Response> => {
    const url = new URL(req.url);
    const path = url.pathname;
    const method = req.method;

    // POST /login
    if (path === "/login" && method === "POST") {
      let body: string;
      try {
        body = await req.text();
      } catch {
        return jsonResponse(400, { error: "invalid_request" });
      }

      let data: unknown;
      try {
        data = JSON.parse(body);
      } catch {
        return jsonResponse(400, { error: "invalid_request" });
      }

      if (data === null || typeof data !== "object" || Array.isArray(data)) {
        return jsonResponse(400, { error: "invalid_request" });
      }

      const obj = data as Record<string, unknown>;
      if (typeof obj.username !== "string" || typeof obj.password !== "string") {
        return jsonResponse(400, { error: "invalid_request" });
      }

      const username = obj.username;
      const password = obj.password;

      const user = userMap.get(username);
      if (!user || user.password !== password) {
        return jsonResponse(401, { error: "invalid_credentials" });
      }

      const nowMs = now().getTime();
      const expiry = nowMs + 3600_000;
      const token = await generateToken(username, expiry);
      const expiresAt = new Date(expiry).toISOString();

      return jsonResponse(200, { token, expiresAt });
    }

    // GET /me
    if (path === "/me" && method === "GET") {
      const token = getTokenFromRequest(req);
      if (!token) return jsonResponse(401, { error: "unauthorized" });
      const user = await verifyToken(token);
      if (!user) return jsonResponse(401, { error: "unauthorized" });
      return jsonResponse(200, { username: user.username, role: user.role });
    }

    // GET /admin/stats
    if (path === "/admin/stats" && method === "GET") {
      const token = getTokenFromRequest(req);
      if (!token) return jsonResponse(401, { error: "unauthorized" });
      const user = await verifyToken(token);
      if (!user) return jsonResponse(401, { error: "unauthorized" });
      if (user.role !== "admin") return jsonResponse(403, { error: "forbidden" });
      const adminCount = users.filter((u) => u.role === "admin").length;
      return jsonResponse(200, { users: users.length, admins: adminCount });
    }

    // POST /logout
    if (path === "/logout" && method === "POST") {
      const token = getTokenFromRequest(req);
      if (!token) return jsonResponse(401, { error: "unauthorized" });
      const user = await verifyToken(token);
      if (!user) return jsonResponse(401, { error: "unauthorized" });
      revokedTokens.add(token);
      return new Response(null, { status: 204 });
    }

    // Everything else
    return jsonResponse(404, { error: "not_found" });
  };
}
